pub(crate) const STYLES: &str = r#"
.df-sheet{--gold:#d9b77a;--ink:#101410;--paper:#f0e3c8;--paper-ink:#30271c;--muted:#7b6951;position:relative;isolation:isolate;min-height:100svh;background:var(--ink);color:#f4eddf;font:15px/1.6 system-ui,sans-serif;overflow:hidden}
.df-sheet *{box-sizing:border-box;min-width:0}.df-sheet [hidden]{display:none!important}.df-sheet p,.df-sheet h1,.df-sheet h2,.df-sheet button,.df-sheet dt,.df-sheet dd{overflow-wrap:anywhere}
.df-sheet .sheet-art{position:absolute;inset:0;width:100%;height:510px;object-fit:cover;object-position:center 43%;z-index:-3}
.df-sheet:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#0b100d90,#0b100d45 120px,#101410c9 340px,#101410 510px),linear-gradient(90deg,#0b100de6,transparent 85%)}
.df-sheet .sheet-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 4vw;border-bottom:1px solid #d9b77a35;background:#0b100d85}
.df-sheet .sheet-brand{color:#efce91;font:26px Georgia,serif;letter-spacing:-1px}.df-sheet .sheet-connection{color:#d8cbb2;font:11px/1.6 system-ui,sans-serif;letter-spacing:.7px;margin:0;max-width:45%;text-align:right}
.df-sheet .sheet-hero{position:relative;width:min(1180px,92%);margin:0 auto;padding:45px 0 30px 26px;border-left:1px solid #d9b77a66}
.df-sheet .sheet-identity{font:11px/1.7 system-ui,sans-serif;letter-spacing:2px;text-transform:uppercase;color:var(--gold);margin:0 0 12px}
.df-sheet h1{font:400 clamp(38px,5vw,62px)/1.1 Georgia,serif;letter-spacing:-1.6px;margin:0 0 12px;max-width:850px;text-shadow:0 3px 30px #000}
.df-sheet .sheet-subtitle{font:16px/1.65 Georgia,serif;color:#eee5d5;max-width:650px;margin:0;text-shadow:0 2px 8px #000}
.df-sheet .sheet-art-fallback{color:#d8cbb2;font:12px/1.6 system-ui,sans-serif;padding:10px 13px;border-left:2px solid var(--gold);background:#24211bee;max-width:650px}
.df-sheet .sheet-notice{width:min(1180px,92%);margin:0 auto 18px;padding:11px 16px;border:1px solid #c7a86b55;border-left:3px solid var(--gold);border-radius:0 5px 5px 0;background:#1c211dee;color:#e5d6b8;font-size:12px}
.df-sheet .sheet-workspace{width:min(1180px,92%);margin:0 auto 48px;padding:24px 28px 30px;border:1px solid #cfad73;border-radius:8px;background:radial-gradient(ellipse at 20% 0,#fff5dd90,transparent 70%),linear-gradient(135deg,#f2e7cd,#e4d3b1);color:var(--paper-ink);box-shadow:0 16px 45px #0005,inset 0 0 0 5px #ac875a15}
.df-sheet .sheet-tabs{display:flex;gap:8px;border-bottom:1px solid #94734955;padding:0 0 18px}
.df-sheet button{font:13px/1.5 system-ui,sans-serif;min-height:48px;max-width:100%;border:1px solid #99794c70;border-radius:5px;padding:11px 16px;background:#f7edd9;color:#4e3b23;cursor:pointer;white-space:normal;touch-action:manipulation;box-shadow:inset 0 1px 0 #fff8}
.df-sheet .sheet-tabs button{flex:1 1 120px;background:#e5d5b6;color:#5f4c33}
.df-sheet button:hover:enabled{border-color:#80603b;background:#fff3d9;color:#30271c}
.df-sheet .sheet-tabs button[aria-selected=true]{border-color:#a98c53;background:linear-gradient(135deg,#26382f,#12241c);color:#f2d899;font-weight:650;box-shadow:0 4px 12px #30271825,inset 0 -3px 0 #c9a567}
.df-sheet .sheet-tabs button[aria-selected=true]:hover:enabled{background:#2d4337;color:#fff1d0}
.df-sheet button:disabled{color:#756d60;border-color:#8c806b55;background:#dcd2bf;cursor:default;box-shadow:none}.df-sheet button[aria-busy=true]{border-style:dashed}
.df-sheet :focus-visible{outline:3px solid #337461;outline-offset:3px}.df-sheet .sheet-hero :focus-visible,.df-sheet .sheet-header :focus-visible{outline-color:#f1d69b}
.df-sheet .sheet-filter{display:grid;gap:7px;margin:20px 0 26px;font-size:12px;color:#665239;max-width:440px}.df-sheet .sheet-filter label{display:grid;gap:7px}
.df-sheet .sheet-filter input{font:16px/1.5 system-ui,sans-serif;color:#30271c;background:#fff7e5;border:1px solid #a3916b;border-radius:5px;padding:10px 13px;min-height:48px;width:100%;box-shadow:inset 0 2px 6px #5d472715}
.df-sheet .sheet-filter input:hover{border-color:#735c3f}.df-sheet .sheet-filter p{margin:0;color:#73502a}
.df-sheet .sheet-tab-panel{display:grid;gap:28px}.df-sheet h2{font:400 26px/1.3 Georgia,serif;color:#45341f;margin:0 0 6px}.df-sheet .sheet-caption{font-size:12px;color:var(--muted);margin:0 0 16px;max-width:750px}
.df-sheet .sheet-section+ .sheet-section{padding-top:24px;border-top:1px solid #94734950}.df-sheet .sheet-rows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-items:start}
.df-sheet .sheet-row{border:1px solid #aa8b5d70;background:#fff7e766;border-radius:6px;min-width:0;box-shadow:0 3px 8px #55401b0c}.df-sheet .sheet-row:hover{border-color:#896a3b}.df-sheet .sheet-row[open]{border-color:#997545;background:#fff6e3;box-shadow:0 4px 16px #55401b18}
.df-sheet .sheet-row-heading{padding:16px;min-height:64px;cursor:pointer;position:relative;display:flex;align-items:center;gap:12px;list-style:none}.df-sheet .sheet-row-heading::-webkit-details-marker{display:none}
.df-sheet .sheet-row-heading:before{content:'+';font:18px/1 Georgia,serif;color:#6f5431;flex:0 0 25px;height:25px;display:grid;place-items:center;border:1px solid #a0825480;border-radius:50%;background:#fff5de80}.df-sheet .sheet-row[open] .sheet-row-heading:before{content:'−';background:#e7d1a4}
.df-sheet .sheet-row-title{font:18px/1.4 Georgia,serif;color:#3d3020;flex:1;overflow-wrap:anywhere}.df-sheet .sheet-row-value{font:600 12px/1.5 system-ui,sans-serif;color:#64502f;text-align:right;max-width:45%;overflow-wrap:anywhere}
.df-sheet .sheet-row[open] .sheet-row-heading{border-bottom:1px solid #94734945}.df-sheet .sheet-row-body{padding:16px 18px 20px}.df-sheet .sheet-row-summary{margin:0 0 17px;color:#66533b;font-size:13px;overflow-wrap:anywhere}
.df-sheet .sheet-section[data-sheet-tab='0'] .sheet-row-value{font:600 20px/1.3 Georgia,serif;color:#315341;background:#dce3c850;border:1px solid #74866a40;border-radius:4px;padding:6px 9px}
.df-sheet .sheet-fields{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:0 16px;font-size:12px;margin:0;border-top:1px solid #94734945}.df-sheet dt{color:#7b6549;padding:10px 0;border-bottom:1px solid #94734930}.df-sheet dd{color:#3c3021;margin:0;padding:10px 0;border-bottom:1px solid #94734930;overflow-wrap:anywhere}
.df-sheet .sheet-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:18px}.df-sheet .sheet-actions:empty{display:none}.df-sheet .sheet-actions button:enabled{color:#f4dfab;border-color:#a98c53;background:linear-gradient(135deg,#304338,#192c21);font-weight:650;box-shadow:0 4px 12px #30271825,inset 0 1px 0 #fff2}.df-sheet .sheet-actions button:hover:enabled{background:#3b5142;color:#fff1d0}
.df-sheet .sheet-empty{color:#6f5b40;text-align:center;padding:28px 20px;border:1px dashed #a3895e;border-radius:6px;background:#fff4db60}
@media(min-width:1000px){.df-sheet .sheet-section[data-sheet-tab='0']:first-child .sheet-rows{grid-template-columns:repeat(3,minmax(0,1fr))}.df-sheet .sheet-section[data-sheet-tab='0']:first-child .sheet-row-heading{flex-wrap:wrap;gap:7px}.df-sheet .sheet-section[data-sheet-tab='0']:first-child .sheet-row-title{font-size:17px}.df-sheet .sheet-section[data-sheet-tab='0']:first-child .sheet-row-value{flex-basis:100%;max-width:none;text-align:center;margin-left:32px}}
@media(min-width:1800px){.df-sheet{font-size:17px}.df-sheet .sheet-workspace{width:min(1420px,92%);padding:32px 36px}.df-sheet .sheet-hero,.df-sheet .sheet-notice{width:min(1420px,92%)}.df-sheet h2{font-size:30px}.df-sheet .sheet-row-title{font-size:21px}.df-sheet .sheet-row-value,.df-sheet .sheet-fields,.df-sheet .sheet-caption,.df-sheet .sheet-row-summary{font-size:15px}.df-sheet button{font-size:16px}}
@media(max-width:700px){.df-sheet .sheet-header{padding:15px 5%;align-items:start;gap:14px}.df-sheet .sheet-brand{font-size:22px}.df-sheet .sheet-connection{max-width:46%;font-size:10px;letter-spacing:.3px}.df-sheet .sheet-hero{width:90%;padding:27px 0 21px 16px}.df-sheet .sheet-identity{font-size:10px;letter-spacing:1px;margin-bottom:9px}.df-sheet h1{font-size:35px;letter-spacing:-1px;margin-bottom:10px}.df-sheet .sheet-subtitle{font-size:14px;line-height:1.6}.df-sheet .sheet-notice{width:90%;padding:10px 12px;margin-bottom:14px;font-size:11px}.df-sheet .sheet-workspace{padding:16px 14px 22px;width:94%;border-radius:6px;margin-bottom:28px}.df-sheet .sheet-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;padding-bottom:15px}.df-sheet .sheet-tabs button{padding:10px 6px;font-size:12px;min-height:46px}.df-sheet .sheet-rows{grid-template-columns:1fr;gap:10px}.df-sheet .sheet-filter{max-width:none;margin:17px 0 22px}.df-sheet h2{font-size:23px}.df-sheet .sheet-caption{font-size:12px;margin-bottom:14px}.df-sheet .sheet-row-heading{padding:13px 11px;gap:9px;flex-wrap:wrap}.df-sheet .sheet-row-heading:before{flex-basis:23px;height:23px}.df-sheet .sheet-row-title{font-size:17px;flex-basis:calc(100% - 32px)}.df-sheet .sheet-row-value{font-size:12px;max-width:none;text-align:left;flex-basis:100%;margin-left:32px}.df-sheet .sheet-section[data-sheet-tab='0'] .sheet-row-value{font-size:21px;flex-basis:auto;min-width:100px;text-align:center}.df-sheet .sheet-row-body{padding:14px 13px 18px}.df-sheet .sheet-fields{grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:0 12px}.df-sheet .sheet-actions button{width:100%;min-height:46px;font-size:13px}.df-sheet .sheet-art{height:410px;object-position:48% center}.df-sheet:before{background:linear-gradient(180deg,#10141085,#10141080 110px,#101410dc 290px,#101410 410px)}.df-sheet .sheet-empty{padding:23px 14px}}
@media(max-width:360px){.df-sheet .sheet-brand{font-size:20px}.df-sheet .sheet-connection{font-size:9px}.df-sheet h1{font-size:31px}.df-sheet .sheet-workspace{padding:14px 12px 20px}.df-sheet .sheet-tabs{grid-template-columns:repeat(2,minmax(0,1fr))}.df-sheet .sheet-tabs button:last-child{grid-column:1 / -1}.df-sheet .sheet-fields{grid-template-columns:minmax(0,1fr);gap:0}.df-sheet dt{border-bottom:0;padding:9px 0 2px}.df-sheet dd{padding:0 0 9px}}
"#;
